function candleChart(){
  const c=comp(lib,'Chart / AAPL intraday',24,Y0+1800,342,244,'#FFFFFF',0);
  const x0=46,x1=342,top=10,bot=200;
  const yFor=v=>bot-((v-100)/(150-100))*(bot-top);
  [150,140,130,120,110,100].forEach(v=>{
    const g=figma.createRectangle();g.name='Grid '+v;g.resize(x1-x0,1);g.x=x0;g.y=yFor(v);g.fills=solid('#F1F0F4');c.appendChild(g);
    const l=txt(c,'Axis $'+v,'$'+v+'.00',0,yFor(v)-8,9,'Medium',C.ink3); l.x=x0-6-l.width;
  });
  const px=[128,131,129,133,132,136,134,138,137,141,139,142,140,143,141,142,142,143.43];
  const n=px.length, slot=(x1-x0)/n, bw=11;
  px.forEach((p,i)=>{
    const prev=i===0?p:px[i-1];
    const up=p>=prev;
    const op=i===0?p-1.6:Math.min(prev,p)-1.2;
    const hi=Math.max(p,prev)+1.8+ (i%3===0?0.9:0);
    const lo=Math.min(p,prev)-1.6-(i%4===0?0.8:0);
    const cx=x0+i*slot+slot/2;
    const wick=figma.createRectangle(); wick.name='Wick '+i; wick.resize(1.5,Math.max(2,yFor(lo)-yFor(hi))); wick.x=cx-0.75; wick.y=yFor(hi); wick.fills=solid(up?C.gain:C.loss); c.appendChild(wick);
    const body=figma.createRectangle(); body.name='Body '+i; body.resize(bw,Math.max(3,Math.abs(yFor(op)-yFor(p)))); body.x=cx-bw/2; body.y=Math.min(yFor(op),yFor(p)); body.cornerRadius=2;
    body.fills=solid(up?C.gain:C.loss); c.appendChild(body);
  });
  ['10am','11am','12pm','1pm','2pm','3pm'].forEach((t,i)=>{
    const l=txt(c,'Time '+t,t,x0+i*((x1-x0)/6)-10,208,9,'Medium',C.ink3);
    l.x=x0+i*((x1-x0)/6)-l.width/2;
  });
  return c;
}
