function frame(p,n,x,y,w,h,fill,r){const f=figma.createFrame();f.name=n;f.x=x;f.y=y;f.resize(w,h);f.fills=fill?solid(fill):[];f.clipsContent=false;if(r!==undefined)f.cornerRadius=r;if(p)p.appendChild(f);return f;}
function instByName(name,parent,x,y){const c=byName(name);if(!c)throw new Error('missing '+name);const i=c.createInstance();parent.appendChild(i);i.x=x;i.y=y;return i;}
function txt(p,n,chars,x,y,size,style,color,o={}){const t=figma.createText();t.name=n;t.fontName={family:'Inter',style};t.characters=chars;t.fontSize=size;t.fills=solid(color);if(o.lh)t.lineHeight={unit:'PIXELS',value:o.lh};if(o.ls)t.letterSpacing={unit:'PERCENT',value:o.ls};if(o.w)t.textAutoResize='HEIGHT',t.resize(o.w,Math.max(t.height,size*1.5));if(p)p.appendChild(t);t.x=x;t.y=y;return t;}
function iconInst(p,name,srcId,x,y,size,color){const s=figma.getNodeById(srcId);const i=s.createInstance();p.appendChild(i);i.rescale(size/i.width);i.x=x;i.y=y;
  if(color){const paint=solid(color);const st=[i];while(st.length){const nd=st.pop();if(nd.type!=='TEXT'&&'fills'in nd&&nd.fills&&nd.fills.length){try{nd.fills=paint;}catch(e){}}if('strokes'in nd&&nd.strokes&&nd.strokes.length){try{nd.strokes=paint;}catch(e){}}if(nd.children)st.push(...nd.children);}}
  return i;}
