function ic(parent,key,x,y,size,color){
  const src='<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">'+S[key].replace(/%C%/g,color)+'</svg>';
  const g=figma.createNodeFromSvg(src);
  parent.appendChild(g);
  g.rescale(size/24); g.x=x; g.y=y;
  return g;
}

