function button(name,x,y,label,o={}){
  const {bg=C.brand,fg='#FFFFFF',border=null,disabled=false,w=374,h=56,icon=null,iconColor=null}=o;
  const c=comp(LIB,name,x,y,w,h,disabled?'#F1F0F3':bg,16);
  if(border){c.strokes=solid(border);c.strokeWeight=1.5;c.strokeAlign='INSIDE';}
  const col=disabled?'#A9A9B4':fg;
  const t=txt(c,'Label',label,0,0,16,'Semi Bold',col);
  t.y=(h-t.height)/2;
  if(icon){
    const total=t.width+8+20;
    t.x=(w-total)/2;
    ic(c,icon,(w-total)/2+t.width+8,(h-20)/2,20,iconColor||col);
  } else t.x=(w-t.width)/2;
